            command([tool('systemctl'),verb,'--all','--type=service','--no-legend','--plain','moonshine@*.service']).stdout.each_line do |line|
              unit = line.split.first
              names << unit if unit && unit.match?(/\Amoonshine@[^\/\s]+\.service\z/)
            end
          end
          names.sort.to_h do |unit|
            enabled = command([tool('systemctl'),'is-enabled',unit],check: false).stdout.strip
            fragment = command([tool('systemctl'),'show',unit,'--property=FragmentPath','--value']).stdout.strip
            ensure!(fragment == HOST_FILES['/usr/lib/systemd/system/moonshine@.service'] || (fragment == '/dev/null' && %w[masked masked-runtime].include?(enabled)), "Conflicting service instance: #{unit}")
            ensure!(%w[enabled enabled-runtime disabled static masked masked-runtime].include?(enabled), "Unsupported service enablement state: #{unit}: #{enabled}")
            active = command([tool('systemctl'),'is-active',unit],check: false).stdout.strip
            ensure!(%w[active inactive failed].include?(active), "Service is transitioning: #{unit}: #{active}")
            ensure!(!(active == 'active' && %w[masked masked-runtime].include?(enabled)), "Cannot restart a masked running instance safely: #{unit}")
