            enabled = command([tool('systemctl'),'is-enabled',unit],check: false).stdout.strip
            fragment = command([tool('systemctl'),'show',unit,'--property=FragmentPath','--value']).stdout.strip
            ensure!(fragment == HOST_FILES['/usr/lib/systemd/system/moonshine@.service'] || (fragment == '/dev/null' && %w[masked masked-runtime].include?(enabled)), "Service ownership changed during cleanup: #{unit}")
