        def check_owned(manifest)
          manifest['host_files'].merge(IMAGE_PATH.to_s=>manifest['image_sha256']).each do |dest,sha|
            path = Pathname(dest)
            secure_path(path,allow_missing: true)
            ensure!(!path.exist? || (path.file? && digest(path) == sha), "Owned file was changed externally: #{path}")
          end
        end
        def uninstall
