          unless value['active']
            ensure!(!IMAGE_PATH.exist? && !IMAGE_PATH.symlink?, 'Untracked active image; refusing cleanup')
            return
          end
          _, manifest = bundle(value['active'])
          check_owned(manifest)
          if value['phase'] == 'active'
            value['services'] = capture_services
            value['recovery'] = value['active']
          end
          value['phase'] = 'removing'
          save(value)
          stop_services(value['services'])
          manifest['host_files'].each_key { |dest| File.unlink(dest) if File.exist?(dest) }
          IMAGE_PATH.unlink if IMAGE_PATH.exist?
          refresh
          command([tool('systemctl'),'daemon-reload'])
          scriptlet(manifest,'postremove',0)
          command([tool('udevadm'),'control','--reload'])
          reset_removed_services(value['services'])
          value.merge!('active'=>nil,'phase'=>'removed')
          save(value)
        end
        def scriptlet(manifest,name,argument)
          command(['/bin/sh','-c',manifest['scriptlets'].fetch(name),"moonshine-#{name}",argument.to_s])
        end
        def build(source)
