            package = path/'release.rpm'
            File.open(source,'rb') do |src|
              ensure!(src.stat.file? && src.stat.size <= MAX_PACKAGE, 'RPM source must be a bounded regular file')
              package.open(File::WRONLY|File::CREAT|File::EXCL,0600) do |dst|
                total = 0
                while (chunk = src.read(1024*1024))
                  total += chunk.bytesize
                  ensure!(total <= MAX_PACKAGE, 'RPM changed size during staging')
                  dst.write(chunk)
                end
              end
            end
            ensure!(digest(package) == RELEASE['sha256'], 'Official RPM SHA-256 mismatch')
            rpm = Rpm.new(package)
            inventory = rpm.validate
            rpm.dependencies.each { |dep| ensure!(command([tool('rpm'),'-q','--whatprovides',dep],check: false).returncode == 0, "Missing host RPM prerequisite: #{dep}. No packages were layered.") }
            tree = path/'extracted'
            tree.mkdir
