            verify_elf(tree)
            host = path/'host'
            HOST_FILES.each do |src,dest|
              target = host/dest.delete_prefix('/')
              target.dirname.mkpath
              FileUtils.mv(tree/src.delete_prefix('/'),target)
            end
            target = host/DROPIN.delete_prefix('/')
            target.dirname.mkpath
            target.binwrite(DROPIN_CONTENT)
            target.chmod(0644)
            nodes(tree).reverse_each { |p| p.rmdir if p != tree && p.directory? && p.children.empty? }
            metadata = tree/'usr/lib/extension-release.d'/('extension-release.'+IMAGE_NAME)
