          mounted = false
          begin
            command([tool('mount'),'-t','erofs','-o','loop,ro',bundle/'image.raw',view])
            mounted = true
            nodes(view).each do |item|
              relative = item.relative_path_from(view).to_s
              logical = relative == '.' ? '/' : '/' + relative
              expected = command([tool('matchpathcon'),'-n',logical]).stdout.strip
              ensure!(context(item) == expected, "Retained image context mismatch: #{logical}")
            end
            verify_elf(view)
            manifest['payload'].each { |logical,sha| ensure!(digest(view/logical.delete_prefix('/')) == sha, 'Retained image payload mismatch') }
