      def main(argv=ARGV)
        options, tools = {}, {}
        parser = OptionParser.new do |p|
          p.banner = 'Usage: moonshine_host.rb ACTION [--rpm FILE] [--bsdtar PATH --mkfs-erofs PATH --fsck-erofs PATH]'
          p.on('--rpm FILE') { |v| options[:rpm] = v }
          %w[bsdtar mkfs.erofs fsck.erofs].each { |n| p.on('--'+n.tr('.','-')+' PATH') { |v| tools[n] = v } }
        end
        parser.parse!(argv)
        action = argv.shift
        ensure!(argv.empty? && %w[inspect install uninstall recover status prepare purge-recovery].include?(action), parser.to_s)
        ensure!(tools.empty? || %w[install prepare].include?(action), 'Conversion-tool paths are only valid for install or prepare')
        if action == 'inspect'
          ensure!(options[:rpm], 'inspect requires --rpm')
          ensure!(digest(options[:rpm]) == RELEASE['sha256'], 'Official RPM SHA-256 mismatch')
          rpm = Rpm.new(options[:rpm])
          puts JSON.pretty_generate('release'=>RELEASE,'inventory'=>rpm.validate,'dependencies'=>rpm.dependencies,'scriptlet_interpreters'=>{'postinstall'=>rpm.tags[1086],'postremove'=>rpm.tags[1088]})
