            ensure!(options[:rpm], "#{action} requires --rpm")
            source = File.binread(__FILE__).sub(/\A#![^\n]*/, '#!'+File.realpath(RbConfig.ruby)+' --disable=rubyopt')
            atomic_write(host.root/'helper.rb',source,0700)
