                       'HOMEBREW_NO_AUTO_UPDATE' => '1', 'HOMEBREW_NO_ANALYTICS' => '1'},
                      brew, 'list', '--cask', '--full-name', '-1')
      end

      def main(argv = ARGV, euid: Process.euid, runner: method(:run))
