          p.banner = 'Usage: moonshine_token_guard.rb --brew FILE --token TAP/CASK'
          p.on('--brew FILE') { |value| options[:brew] = value }
          p.on('--token TOKEN') { |value| options[:token] = value }
        end
        parser.parse!(argv)
